text:
{
  "patches": [
    {
      "chapter": 1,
      "old": "朝戏台边缘的一个看热闹少年飞去。",
      "new": "朝戏台边缘一个登记契券的少年飞去。",
      "reason": "恢复已批准锚点中受偏刃威胁的契券人员身份，保留少年身份及后文指代。"
    },
    {
      "chapter": 1,
      "old": "顾临川能感觉到它的脚踩着木板，也能感觉到它正看着什么。",
      "new": "顾临川看见它的脚稳稳踩着木板，正转头望向台边。",
      "reason": "分离期间不能实时共享影身的触感和视觉；改为本体现场能够看见的动作。"
    },
    {
      "chapter": 1,
      "old": "他走到影身面前，伸手从影身肩头穿过去。手掌陷入黑色轮廓，带出一阵冰冷的影力，却没有碰到实体血肉。",
      "new": "他走到影身面前，伸手按住它的肩头。掌下是结实的肩膀，黑色轮廓在火光里微微晃动。",
      "reason": "Frozen Power Core 批准的是另一具完整身体，不能写成手掌可以直接穿透的虚影。"
    },
    {
      "chapter": 1,
      "old": "走到他面前时，黑影重新落回他的脚下。",
      "new": "走到他面前，碰上他伸出的手时，黑影重新落回他的脚下。",
      "reason": "补足两具身体接触后合并的永久边界。"
    },
    {
      "chapter": 2,
      "old": "顾临川脑中立刻多出另一边的画面。",
      "new": "货棚那边，影身也在行动。",
      "reason": "同域修复实时共享视觉的问题；保留影身一侧独立发生的守货行动。"
    },
    {
      "chapter": 2,
      "old": "顾临川回到仓院时，影身已经把那个偷药箱的少年按在墙边。",
      "new": "顾临川回到仓院时，影身已经把那个偷药箱的少年按在墙边。姚谦接手看住少年，他便伸手碰住影身，让它合回；守箱那边的经历这才涌进脑中。",
      "reason": "原文此后直到本章结束都未收回影身，遗漏短时分影的结束及经历回流；用现场既有人物完成接手和接触合并。"
    },
    {
      "chapter": 2,
      "old": "说完，他把一块薄铜牌扔给顾临川。",
      "new": "说完，他把顾临川那份护送契券递给他，又把一块薄铜牌扔了过去。",
      "reason": "契券此前被姚谦收起，原文只交付铜牌，未兑现本章获得护卫契券及第3章携正式契券离开的物品状态。"
    },
    {
      "chapter": 2,
      "old": "他把银角子和铜牌一起收进贴身的小袋里，忽然很想去街尾买那碗总舍不得吃的辣肉面。",
      "new": "他把银角子收进贴身的小袋里，铜牌仍握在手里，忽然很想去街尾买那碗总舍不得吃的辣肉面。",
      "reason": "铜牌刚被收入口袋，紧接着陆绾却看见它仍在手里；修复同一物件的位置 stale。"
    },
    {
      "chapter": 3,
      "old": "父亲把铜牌放回去，说：“你十三岁抄错货单，少算了三十七个银角子。后来你每次写数字都要多看两遍，我知道。”",
      "new": "父亲把铜牌放回去，说：“你十三岁抄错货单，少算了一笔钱，家里用了两个月才补平。”",
      "reason": "Frozen Human Core 只批准少收一笔钱、两个月补平；未批准精确旧账金额及此后每次复核数字的过去事实。"
    },
    {
      "chapter": 3,
      "old": "他忽然想起后厨失火那年，母亲先抱着账册冲出来，父亲蹲在雨里一张张晾湿掉的货单。",
      "new": "他忽然想起后厨失火那年，他和母亲先救出住客与账册，后来又花了半年还债、重修屋顶。",
      "reason": "删除未批准的父亲雨中晾货单旧事，恢复已批准的救援参与者、被救对象及火灾后果。"
    },
    {
      "chapter": 3,
      "old": "陆绾没理他，低头检查车轮上的泥。",
      "new": "陆绾没理他，低头检查车轮上的泥。她说：“药和期限都不能迁就你扬名，守药的额外收益也少。”\n\n“我接。”顾临川说。",
      "reason": "恢复本章完全漏失的选择结果：顾临川接受较低的额外收益承担同行护送，同时接受陆绾独立的送药期限。"
    },
    {
      "chapter": 3,
      "old": "他手里拿着一枚传讯铜片，铜片一直没有亮。",
      "new": "他手里拿着一张路单，青石驿回报那一栏还空着。",
      "reason": "Approved Plan 只批准驿站失联，没有批准以铜片亮灭接收远程讯息的机制；保留未收到路况回报的既定事实。"
    },
    {
      "chapter": 3,
      "old": "契券按半日工钱结，不追责。",
      "new": "不追责。",
      "reason": "删除未经批准的半日工钱结算承诺，保留姚谦允许退出的现场安排。"
    },
    {
      "chapter": 3,
      "old": "姚谦手里的传讯铜片始终没有亮。",
      "new": "直到岔口，青石驿仍没有回报。姚谦收起路单，叫前队转向折日峡外围。",
      "reason": "清除同一通信机制的另一处出现，并恢复本章结尾由条件性提议落实为确定绕行的批准结果。"
    },
    {
      "chapter": 4,
      "old": "顾临川立刻收回影身。",
      "new": "顾临川立刻让影身沿原路退回，伸手与它碰在一起。",
      "reason": "影身尚在二十多步外，不能直接收回合并；补足普通原路返回与接触，不新增召回机制。"
    },
    {
      "chapter": 4,
      "old": "顾临川看见陆绾的药车被调到了队伍中后段，旁边还跟着一名腿上有旧伤的护卫。那护卫叫石勇，原本守后队，昨夜巡路时被碎石砸伤了膝盖，走路一瘸一拐。",
      "new": "顾临川看见陆绾的药车被调到了队伍中后段，旁边还跟着一名腿上有伤的护卫。那护卫叫石勇，原本守后队，膝盖受了伤，走路一瘸一拐。",
      "reason": "保留计划所需的受伤护卫及当前伤处，删除未批准的昨夜巡路受伤事件和旧伤定性。"
    },
    {
      "chapter": 5,
      "old": "顾临川本体胸口像被人重重砸了一拳。他立刻明白，影身承受的拉力会回到自己身上。",
      "new": "影身胸口像被人重重砸了一拳，却仍攥着绷紧的影绳。",
      "reason": "影身承受的普通拉力不能实时传给本体；其伤势与损耗应在接触合并时归回同一身体。"
    },
    {
      "chapter": 5,
      "old": "顾临川自己的右臂也立刻传来撕裂般的疼。",
      "new": "顾临川看见那道伤口，知道合回后仍得落在自己身上。",
      "reason": "同域修复影身普通割伤立即同步到本体的问题，保留主角知道合并后必须承担伤势的判断。"
    },
    {
      "chapter": 5,
      "old": "影身的手臂被刺划得支离破碎，顾临川眼前一黑，嘴里尝到血味。他却借着异兽甩动的方向，把本体凝出的影绳绕上药车车轴。",
      "new": "影身的手臂又被硬刺划出几道血口，仍扣住硬刺不放。顾临川借着异兽甩动的方向，把本体凝出的影绳绕上药车车轴。",
      "reason": "删除普通割伤的即时跨身反馈；将支离破碎及本体反噬恢复为本章允许的局部受伤，避免提前兑现后续首次影身撕裂与严重反噬。"
    },
    {
      "chapter": 5,
      "old": "顾临川抬手让它合回。",
      "new": "顾临川伸手碰住它，让它合回。",
      "reason": "同域补足接触合并条件，使随后右臂伤势和胸口闷痛回流符合 Frozen Power Core。"
    }
  ],
  "upstream_conflicts": []
}
